INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p229:fact:damper_adjustment_method','summary','en','Hold damper vertically in a vice with soft jaws, engage adjusting pins by compressing and turning the dust cover anticlockwise, mark the zero relationship, then increase setting by half a clockwise turn for each 48,000 miles completed.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
