INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p231:fact:front_bump_rubber','title','en','Front bump rubber service','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p231:fact:front_bump_rubber','summary','en','Raise and support one front side, remove the road wheel, use an 11 mm spanner to remove the bump-rubber nut, collect the spacer, then refit spacer, rubber, nut and wheel.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
