INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p231:fact:front_rebound_rubber','summary','en','Raise and support one front side, jack beneath the lower suspension arm, remove the rebound-rubber retaining screw and rubber, then refit and remove the jack before lowering the vehicle.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
