INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p232:fact:front_damper_removal','summary','en','Raise and support one front side, remove wheel and both damper mounting fasteners/spacer, remove damper and store it upright if it will be refitted.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
