INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p233:fact:rear_damper_removal','summary','en','For LH side first remove the fuel tank; support the raised rear side, remove wheel, disconnect upper and lower damper mountings, compress and remove the damper, and store it upright if it will be refitted.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
